void labelJars(List<Jar> jars, Loan loan) {
    try {
        for (int i = 0; i < jars.size(); i++) {
            if (i % 500 == 0 && Thread.currentThread().isInterrupted()) return;   // cooperate with a cancel
            try {
                label(jars.get(i));
            } catch (LabelException e) {                                      // only what we expect
                log.warn("skipping {}", jars.get(i).id(), e);
            }
        }
    } finally {
        boolean interrupted = Thread.interrupted();
        try { loan.giveBack(); }                                              // blocking cleanup
        finally { if (interrupted) Thread.currentThread().interrupt(); }
    }
}

